import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class LongSet {
        private final int mask;
        private final long[] keys;
        private final boolean[] used;

        public LongSet(int capacityPowerOfTwo) {
            this.mask = capacityPowerOfTwo - 1;
            this.keys = new long[capacityPowerOfTwo];
            this.used = new boolean[capacityPowerOfTwo];
        }

        private int hash(long key) {
            key ^= (key >>> 33);
            key *= 0xff51afd7ed558ccdL;
            key ^= (key >>> 33);
            key *= 0xc4ceb9fe1a85ec53L;
            key ^= (key >>> 33);
            return (int) key & mask;
        }

        public void add(long key) {
            int idx = hash(key);
            while (used[idx]) {
                if (keys[idx] == key) return;
                idx = (idx + 1) & mask;
            }
            used[idx] = true;
            keys[idx] = key;
        }

        public boolean contains(long key) {
            int idx = hash(key);
            while (used[idx]) {
                if (keys[idx] == key) return true;
                idx = (idx + 1) & mask;
            }
            return false;
        }
    }

    private static long encode(String s, int start, int end) {
        long code = 0;
        for (int i = start; i < end; i++) {
            code = (code << 5) | (s.charAt(i) - 'a' + 1);
        }
        return code;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        String nStr = scanner.next();
        if (nStr == null) return;
        int n = Integer.parseInt(nStr);

        String[] strings = new String[n];
        for (int i = 0; i < n; i++) {
            strings[i] = scanner.next();
        }

        LongSet prefixes = new LongSet(1 << 19);
        LongSet suffixes = new LongSet(1 << 19);
        LongSet substrings = new LongSet(1 << 21);

        for (int k = 0; k < n; k++) {
            String s = strings[k];
            int len = s.length();

            boolean invalid = false;

            if (k > 0) {
                long fullCode = encode(s, 0, len);
                if (substrings.contains(fullCode)) {
                    invalid = true;
                } else {
                    for (int l = 1; l < len; l++) {
                        long prefCode = encode(s, 0, l);
                        long suffCode = encode(s, l, len);
                        if (suffixes.contains(prefCode) && prefixes.contains(suffCode)) {
                            invalid = true;
                            break;
                        }
                    }
                }
            }

            if (invalid) {
                System.out.println(s);
                return;
            }

            for (int i = 0; i < len; i++) {
                long code = 0;
                for (int j = i; j < len; j++) {
                    code = (code << 5) | (s.charAt(j) - 'a' + 1);
                    substrings.add(code);
                }
            }

            for (int l = 1; l <= len; l++) {
                prefixes.add(encode(s, 0, l));
                suffixes.add(encode(s, len - l, len));
            }
        }

        System.out.println("ok");
    }
}
